function TasksNewInner() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.tasks.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push(`/tasks/${text(row.id)}`);
    }
  });
  return (
    <Pane title="New task" actions={<Link href="/tasks" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>}>
      <TasksForm
        fields={TASKS_CREATE}
        initial={EMPTY_TASKS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toTasksCreateInput(values))}
      />
    </Pane>
  );
}

function TasksDetailInner() {
  const { id: rawId } = useParams<{ id: string }>();
  const id = idOf(rawId);
  const router = useRouter();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  useEffect(() => {
    setEditing(false);
    setOpenAction(null);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.tasks.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["tasks"]["update"]) => client.tasks.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["tasks"]["delete"]) => client.tasks.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push("/tasks");
    }
  });
  const remindAction = useMutation({
    mutationFn: (input: Inputs["tasks"]["remind"]) => client.tasks.remind(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.title) || "Task " + text(row.id)}
      actions={
        <>
          <Link href="/tasks" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>
          {canRemind(user, row) ? (
            <Button variant="outline" size="sm" disabled={remindAction.isPending} onClick={() => remindAction.mutate({ id })}>
              Remind
            </Button>
          ) : null}
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this task?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >

      <ErrorNote error={remindAction.error} className="mb-4" />
      {editing ? (
        <TasksForm
          fields={TASKS_UPDATE}
          initial={tasksFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toTasksUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Project">{text(row.project_id) || "—"}</FieldRow>
        <FieldRow label="Title">{text(row.title) || "—"}</FieldRow>
        <FieldRow label="Done">{row.done == null ? "—" : <Badge variant={row.done ? "default" : "outline"}>{yesNo(row.done)}</Badge>}</FieldRow>
        <FieldRow label="Assignee">{text(row.assignee_id) || "—"}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        <FieldRow label="Due At">{formatDateTime(row.due_at) || "—"}</FieldRow>
        <FieldRow label="Reminded At">{formatDateTime(row.reminded_at) || "—"}</FieldRow>
        </dl>
      )}
    </Pane>
  );
}

